sysauto_script.script:
// REST Medic — Daily Health Scan
// Copyright (C) 2026 Vladimir Kapustin
// SPDX-License-Identifier: AGPL-3.0

(function() {
    try {
        var engine = new RESTMedicEngine();
        var alerter = new RESTMedicAlerter();

        var scanResult = engine.scanAll();
        gs.info('REST Medic daily scan complete: ' + scanResult.endpoint_count + ' endpoints, ' +
                scanResult.healthy + ' healthy, ' + scanResult.warning + ' warning, ' +
                scanResult.critical + ' critical, avg score: ' + scanResult.avg_score);

        var alertResult = alerter.checkThresholds();
        if (alertResult.alerts_sent > 0) {
            gs.info('REST Medic: ' + alertResult.alerts_sent + ' alerts sent for ' + alertResult.endpoints_checked + ' endpoints checked.');
        }
    } catch (e) {
        gs.error('REST Medic daily scan failed: ' + e.toString());
    }
})();
